"""
ATHAR agent layer: triage the candidate objects of an 11 run and DRAFT the evidence report.

Division of labour (deliberate, for admissibility):
  * TRIAGE is deterministic code, not the LLM: the review queue order is a documented rule anyone can
    re-derive (tier-1 first, then multi-view confirmed, then fused score).  The LLM never decides
    which candidate a human sees first or whether something is evidence.
  * The report's FACTS section (counts, classes, positions, hashes) is generated by code from the
    human-APPROVED decisions only.  The LLM writes the narrative paragraph from those facts and
    nothing else; any number in its text that does not appear in the facts is flagged
    ("unsupported_numbers") so the reviewer sees possible hallucinations.
  * The output is a DRAFT.  Its SHA-256, the backend, model and prompt hash are written into the
    review chain (record_type "agent_draft").  It becomes part of a case file only after a person
    signs off on it.

Backends (all local; nothing leaves the machine):
  StubBackend    deterministic template text -- tests and CI, no model needed
  OllamaBackend  an Ollama server on the loopback interface (default http://127.0.0.1:11434);
                 any non-loopback host is refused.  temperature 0 and a fixed seed.

  python -m athar.agent triage <run_dir>
  python -m athar.agent draft  <run_dir> --reviewer "<name>" [--backend ollama --model llama3.1:8b]
"""
from __future__ import annotations

import argparse
import hashlib
import ipaddress
import json
import re
import sys
import urllib.parse
import urllib.request
from pathlib import Path
from typing import Optional, Protocol

from . import review


class LLMBackend(Protocol):
    name: str
    model: str

    def generate(self, prompt: str, seed: int = 0) -> str: ...


class StubBackend:
    """Deterministic, model-free.  Same facts -> same text, byte for byte."""
    name = "stub"
    model = "deterministic-template-v1"

    def generate(self, prompt: str, seed: int = 0) -> str:
        m = re.search(r"<facts>\n(.*)\n</facts>", prompt, re.S)
        facts = json.loads(m.group(1)) if m else {}
        n = facts.get("n_approved", 0)
        classes = ", ".join(f"{c} ({k})" for c, k in sorted(facts.get("approved_by_class", {}).items())) or "none"
        return (f"A human reviewer approved {n} of {facts.get('n_candidates', 0)} machine-detected candidate "
                f"objects in this run. Approved classes: {classes}. {facts.get('n_tier1_approved', 0)} approved "
                f"objects are tier-1 hazards. {facts.get('n_rejected', 0)} candidates were rejected and "
                f"{facts.get('n_unreviewed', 0)} remain unreviewed. All figures are taken from the reviewed, "
                f"hash-chained evidence log.")


def _is_loopback(host: str) -> bool:
    if host in ("localhost",):
        return True
    try:
        return ipaddress.ip_address(host).is_loopback
    except ValueError:
        return False


class OllamaBackend:
    name = "ollama"

    def __init__(self, model: str, url: str = "http://127.0.0.1:11434", timeout_s: float = 300.0):
        u = urllib.parse.urlparse(url)
        if u.scheme != "http" or not u.hostname or not _is_loopback(u.hostname):
            raise ValueError(f"OllamaBackend only talks to a loopback server (got {url!r}): "
                             f"inference must stay on this machine")
        self.model, self.url, self.timeout_s = model, url.rstrip("/"), timeout_s
        # no proxy, ever: a configured HTTP(S)_PROXY must not route the evidence anywhere
        self._opener = urllib.request.build_opener(urllib.request.ProxyHandler({}))

    def _post(self, path: str, body: dict) -> dict:
        req = urllib.request.Request(self.url + path, data=json.dumps(body).encode(),
                                     headers={"Content-Type": "application/json"})
        with self._opener.open(req, timeout=self.timeout_s) as r:
            return json.loads(r.read().decode())

    def model_digest(self) -> Optional[str]:
        try:
            return self._post("/api/show", {"model": self.model}).get("digest")
        except Exception:
            return None

    def generate(self, prompt: str, seed: int = 0) -> str:
        r = self._post("/api/generate", {"model": self.model, "prompt": prompt, "stream": False,
                                         "options": {"temperature": 0, "seed": seed}})
        return r.get("response", "")


def triage(objects: list) -> list:
    """Deterministic review-queue order.  Returns new dicts with 'triage_rank' and 'triage_reason'."""
    def key(o):
        return (0 if o.get("tier") == 1 else 1, 0 if o.get("confirmed") else 1,
                -(o.get("score") or 0.0), o.get("track_id") if o.get("track_id") is not None else 1 << 30)
    out = []
    for i, o in enumerate(sorted(objects, key=key), 1):
        why = ["tier-1 hazard" if o.get("tier") == 1 else "tier-2",
               "multi-view confirmed" if o.get("confirmed") else "not multi-view confirmed",
               f"score {o.get('score')}"]
        out.append({**o, "triage_rank": i, "triage_reason": "; ".join(why)})
    return out


def build_facts(run_dir: Path) -> dict:
    objs = {o["track_id"]: o for o in review.evidence_objects(run_dir)}
    dec = review.current_decisions(run_dir)
    approved, rejected = [], []
    for tid, d in sorted(dec.items()):
        o = objs.get(tid)
        if o is None:
            continue
        cls = d.get("reviewer_class") or o["class_name"]
        item = {"track_id": tid, "class": cls, "machine_class": o["class_name"], "tier": o.get("tier"),
                "ground_position": o.get("ground_position"), "gps": o.get("gps"),
                "capture_time_utc": o.get("capture_time_utc"), "capture_time_local": o.get("capture_time_local"),
                "image_sha256": o.get("image_sha256"), "evidence_record_hash": o["evidence_record_hash"],
                "decision_record_hash": d["record_hash"], "reviewer": d["reviewer"], "note": d.get("note")}
        (approved if d["decision"] == "approve" else rejected).append(item)
    by_cls = {}
    for a in approved:
        by_cls[a["class"]] = by_cls.get(a["class"], 0) + 1
    anchor = review.evidence_anchor(run_dir)
    return {"n_candidates": len(objs), "n_approved": len(approved), "n_rejected": len(rejected),
            "n_unreviewed": len(objs) - len(approved) - len(rejected),
            "n_tier1_approved": sum(a["tier"] == 1 for a in approved), "approved_by_class": by_cls,
            "approved": approved, "rejected_track_ids": [r["track_id"] for r in rejected],
            "evidence_log_sha256": anchor["evidence_log_sha256"],
            "evidence_last_record_hash": anchor["evidence_last_record_hash"],
            "evidence_head_fingerprint": anchor["evidence_head_fingerprint"]}


PROMPT = """You are drafting one paragraph of an environmental-enforcement evidence report.
Use ONLY the facts between <facts> tags. Do not add numbers, places, dates, causes or legal conclusions
that are not in the facts. Do not speculate about who dumped the waste. Plain, neutral language.
<facts>
{facts}
</facts>
Paragraph:"""


_NUM = re.compile(r"(?<![\w.])\d+(?:\.\d+)?(?![\w])")


def _numbers(text: str) -> set:
    """Standalone numbers (not digits inside hashes / identifiers); 'tier-1' is a name, not a count."""
    return set(_NUM.findall(re.sub(r"tier-[12]", " ", text)))


def draft_report(run_dir: Path, backend: LLMBackend, session: Optional[review.ReviewSession] = None,
                 seed: int = 0) -> dict:
    run_dir = Path(run_dir)
    facts = build_facts(run_dir)
    summary = {k: v for k, v in facts.items() if k != "approved"}
    prompt = PROMPT.format(facts=json.dumps(summary, sort_keys=True, indent=1))
    narrative = backend.generate(prompt, seed=seed).strip()
    allowed = _numbers(json.dumps({k: v for k, v in summary.items()
                                   if not any(w in k for w in ("sha256", "hash", "fingerprint"))}))
    unsupported = sorted(_numbers(narrative) - allowed, key=lambda s: float(s))
    draft = {"status": "DRAFT - generated by the ATHAR agent; not evidence until a reviewer signs it off",
             "backend": backend.name, "model": backend.model,
             "model_digest": backend.model_digest() if hasattr(backend, "model_digest") else None,
             "seed": seed, "prompt_sha256": hashlib.sha256(prompt.encode()).hexdigest(),
             "narrative": narrative, "unsupported_numbers": unsupported, "facts": facts}
    body = json.dumps(draft, indent=2, sort_keys=True, default=str).encode()
    out = run_dir / "agent_drafts"
    out.mkdir(exist_ok=True)
    sha = hashlib.sha256(body).hexdigest()
    path = out / f"report_draft_{sha[:16]}.json"
    path.write_bytes(body)
    if session is not None:
        session.log_event("agent_draft", backend=backend.name, model=backend.model,
                          model_digest=draft["model_digest"], prompt_sha256=draft["prompt_sha256"],
                          draft_file=f"agent_drafts/{path.name}", draft_sha256=sha,
                          n_unsupported_numbers=len(unsupported))
    return {"path": str(path), "sha256": sha, **draft}


def make_backend(name: str, model: Optional[str] = None, url: str = "http://127.0.0.1:11434") -> LLMBackend:
    if name == "stub":
        return StubBackend()
    if name == "ollama":
        if not model:
            raise SystemExit("--model is required for the ollama backend")
        return OllamaBackend(model, url)
    raise SystemExit(f"unknown backend {name}")


def main(argv=None) -> int:
    ap = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    sub = ap.add_subparsers(dest="cmd", required=True)
    t = sub.add_parser("triage")
    t.add_argument("run_dir")
    d = sub.add_parser("draft")
    d.add_argument("run_dir")
    d.add_argument("--reviewer", required=True, help="who requested the draft (recorded in the review chain)")
    d.add_argument("--backend", choices=["stub", "ollama"], default="stub")
    d.add_argument("--model", default=None)
    d.add_argument("--ollama_url", default="http://127.0.0.1:11434")
    d.add_argument("--seed", type=int, default=0)
    a = ap.parse_args(argv)
    if a.cmd == "triage":
        for o in triage(review.evidence_objects(Path(a.run_dir))):
            print(f"  #{o['triage_rank']:>3}  track {o['track_id']:>5}  {o['class_name']:<16} {o['triage_reason']}")
        return 0
    s = review.ReviewSession(Path(a.run_dir), a.reviewer)
    r = draft_report(Path(a.run_dir), make_backend(a.backend, a.model, a.ollama_url), s, a.seed)
    print(r["narrative"])
    print(f"\n  draft -> {r['path']}  (sha256 {r['sha256'][:16]}..., logged in the review chain)")
    if r["unsupported_numbers"]:
        print(f"  WARNING: numbers not in the facts: {r['unsupported_numbers']} -- check the narrative")
    return 0


if __name__ == "__main__":
    sys.exit(main())
